Translate("zhCN", "wetlands", {
	title = "湿地",
	aliases = { "湿地地区" },
	sections = {
		{
			title = "概述",
			text = [=[湿地是一片广阔的{link:swamp-of-sorrows}沼泽{/link}之地，遍布芦苇与缓缓流淌的黑水，位于卡兹莫丹群山以北。一年中大半时间，这里都笼罩在雾中。一条大路贯穿其间：它从南方的{link:dun-algaz}丹奥加兹{/link}攀出，向北经过古老{link:dwarves}矮人{/link}要塞的废墟，止于{link:thandol-span}萨多尔大桥{/link}。这座桥将矮人的土地与北方的{link:humans}人类{/link}王国相连。另一条路向西通往大海，{link:menethil-harbor}米奈希尔港{/link}在那里为{link:alliance}联盟{/link}守望海岸。这里向来是一片艰苦之地，鳄鱼与迅猛龙众多，安逸却难寻。如今，它也是一片战火之地。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载是谁最先在这片{link:swamp-of-sorrows}沼泽{/link}中垒起石头。{link:dwarves}矮人{/link}宣称这里归他们所有，已有许多个世纪。东方矗立着山中要塞{link:grim-batol}格瑞姆巴托{/link}，曾是蛮锤部族的王座所在。在三锤之战中，{link:dark-iron-dwarves}黑铁矮人{/link}进攻格瑞姆巴托，在那里释放的黑暗巫术使要塞遭到玷污。蛮锤矮人弃之而去，北上前往{link:the-hinterlands}辛特兰{/link}的群峰。{link:explorers-league}探险者协会{/link}至今仍在淤泥下发现更古老的东西：巨兽的骸骨，以及刻有某种文字的石头，那文字并非出自任何矮人之手。]=],
		},
		{
			title = "当今",
			text = [=[{link:menethil-harbor}米奈希尔港{/link}在{link:kingdom-of-ironforge}铁炉堡王国{/link}的{link:dwarves}矮人{/link}治下，为{link:alliance}联盟{/link}守卫西海岸。城墙之外，湿地正在分崩离析。{link:dark-iron-dwarves}黑铁{/link}破坏者炸毁了{link:thandol-span}萨多尔大桥{/link}，夺取了{link:dun-modr}丹莫德{/link}，守卫它们的军团残部在废墟中等待一支永远不来的援军。{link:dragonmaw-clan}龙喉氏族{/link}的{link:orcs}兽人{/link}在{link:second-war}第二次战争{/link}后被击败并四散，如今却有了新的酋长和新的营地。他们已推进到{link:dun-algaz}丹奥加兹{/link}，威胁要切断米奈希尔与{link:loch-modan}洛克莫丹{/link}的联系。在{link:whelgar-s-excavation-site}维尔加挖掘场{/link}，迅猛龙杀死了{link:explorers-league}探险者协会{/link}挖掘队的大部分成员。在那处挖掘场上方，雾气开始从山上飘落，高处有光芒闪烁，石质构造体在无人涉足已久的地方行走。唯一的好消息来自海上：新的航船如今从米奈希尔驶往{link:southshore}南海镇{/link}，再前往{link:auberdine}奥伯丁{/link}。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}。{/b}士兵、矿工、牧师与学者驻守{link:menethil-harbor}米奈希尔港{/link}、{link:dun-modr}丹莫德{/link}城外的营地以及{link:explorers-league}探险者协会{/link}的挖掘场。
• {b}米奈希尔的居民。{/b}古老王国的{link:humans}人类{/link}与矮人一同在码头、酒馆和制革坊中劳作。
• {b}{link:dragonmaw-clan}龙喉氏族{/link}。{/b}曾骑着红龙出征的{link:orcs}兽人{/link}，如今扎营于大路以东的丘陵中。
• {b}{link:dark-iron-dwarves}黑铁矮人{/link}。{/b}他们的破坏者、掘地者和术士占据着丹莫德与{link:direforge-hill}恶铁岭{/link}。
• {b}藓皮豺狼人。{/b}{link:swamp-of-sorrows}沼泽{/link}中的一个{link:gnolls}豺狼人{/link}部族，数量已多到这片土地养活不了。
• {b}蓝腮鱼人。{/b}袭扰海岸及过往商船的{link:murlocs}鱼人{/link}。
• {b}溺亡者。{/b}受诅咒的水手仍在西北海岸{link:the-lost-fleet}失落的舰队{/link}的残骸中游荡。]=],
		},
		{
			title = "历史",
			text = [=[• {b}三锤之战。{/b}三个部族的战争过后，{link:grim-batol}格瑞姆巴托{/link}陷入沉寂，蛮锤{link:dwarves}矮人{/link}离开了湿地。
• {b}{link:second-war}第二次战争{/link}。{/b}{link:horde}部落{/link}席卷了卡兹莫丹。{link:dragonmaw-clan}龙喉氏族{/link}将格瑞姆巴托作为据点，{link:orcs}兽人{/link}在西海岸修建了一座港口，以便从海上进攻{link:hillsbrad-foothills}希尔斯布莱德{/link}。受兽人驱使的红龙在这片海岸外焚毁了{link:kul-tiras}库尔提拉斯{/link}的{link:third-fleet}第三舰队{/link}。
• {b}米奈希尔。{/b}{link:daelin-proudmoore}戴林·普罗德摩尔{/link}上将将兽人逐出了他们的港口，{link:alliance}联盟{/link}在同一片土地上建起了自己的港口，以国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}命名。
• {b}当今。{/b}{link:dark-iron-dwarves}黑铁矮人{/link}在北方崛起，龙喉氏族在东方卷土重来，而{link:ironforge}铁炉堡{/link}的预备军被派往其他战线作战。]=],
		},
		{
			title = "湿地传说",
			text = [=[• 米奈希尔制革坊的鳄鱼皮远销世界各地的港口。
• 一个名为{link:rethiel-the-greenwarden}绿色守护者{/link}的{link:swamp-of-sorrows}沼泽{/link}之灵，在通往{link:dun-modr}丹莫德{/link}的岔路以东的鳄鱼群中行走。寻找它的人会被告诫：他们将一去不回。
• 藓皮{link:gnolls}豺狼人{/link}焚烧活树取暖，绿色守护者至今没有原谅他们。
• {link:third-fleet}第三舰队{/link}的最后一名幸存者说，他在梦中仍能听见溺亡兄弟们的呻吟。]=],
		},
	},
})

Translate("zhCN", "menethil-harbor", {
	title = "米奈希尔港",
	sections = {
		{
			title = "概述",
			text = [=[米奈希尔港是{link:alliance}联盟{/link}在{link:wetlands}湿地{/link}西海岸的港口。它建在{link:horde}部落{/link}当年为{link:second-war}第二次战争{/link}造船的地方，他们从卡兹莫丹掠来的木材和铁料，至今仍有许多散落在码头四周。港口的城堡以国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}之名命名。{link:ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}统领这里，{link:captain-stoutfist}斯托菲队长{/link}在米奈希尔城堡的作战室中筹划防务。航船从这里的码头驶往{link:auberdine}奥伯丁{/link}，驶往海那边的{link:theramore-isle}塞拉摩{/link}，如今也驶往{link:southshore}南海镇{/link}。在深水旅店里，水手、学者、密探和一名醉醺醺的{link:third-fleet}第三舰队{/link}幸存者同桌而坐。]=],
		},
	},
})

Translate("zhCN", "dun-modr", {
	title = "丹莫德",
	sections = {
		{
			title = "概述",
			text = [=[丹莫德是{link:wetlands}湿地{/link}北部的一座{link:dwarves}矮人{/link}城镇，位于通往{link:thandol-span}萨多尔大桥{/link}的路上。一支{link:ironforge}铁炉堡{/link}军团曾驻守此城及其后的大桥。{link:dark-iron-dwarves}黑铁矮人{/link}先袭击了大桥，又在军团来不及重整之前扑向城镇，大部分矮人遇难。{link:longbraid-the-grim}坚毅者长须{/link}吹响了撤退号。他的军团残部如今就扎营在城墙外，而黑铁士兵、掘地者和爆破手占据着街道。有人看见他们中间锁着一个火焰生物，还有一个名叫莫德的{link:elements}元素{/link}生物在废墟中游荡。]=],
		},
	},
})

Translate("zhCN", "thandol-span", {
	title = "萨多尔大桥",
	aliases = { "萨多尔桥" },
	sections = {
		{
			title = "概述",
			text = [=[萨多尔大桥是{link:wetlands}湿地{/link}北缘的巨桥。它横跨一道深谷，通往{link:arathi-highlands}阿拉希高地{/link}，承载着卡兹莫丹与北方大地之间的主要道路。{link:dark-iron-dwarves}黑铁矮人{/link}在一次伏击中炸毁了它的西桥，许多{link:dwarves}矮人{/link}随之丧生，其中包括{link:longbraid-the-grim}坚毅者长须{/link}的兄弟。这一计划出自一个名叫{link:kam-deepfury}卡姆·深怒{/link}的黑铁矮人之手。他的手下在深谷对面藏下了更多炸药，要将剩下的部分也炸毁。一旦大桥倒塌，矮人就将失去通往北方的主要补给线。]=],
		},
	},
})

Translate("zhCN", "whelgar-s-excavation-site", {
	title = "维尔加挖掘场",
	aliases = { "维尔加挖掘点" },
	sections = {
		{
			title = "概述",
			text = [=[维尔加挖掘场是{link:explorers-league}探险者协会{/link}在{link:wetlands}湿地{/link}中部的一处挖掘点。{link:prospector-whelgar}勘察员维尔加{/link}的队伍正在发掘古代遗物，这时他们开始挖出巨大的骸骨。不久之后，{link:swamp-of-sorrows}沼泽{/link}中的斑纹迅猛龙席卷了营地。许多挖掘者死去。三名幸存者坚守在营地废墟上方的一处断崖上。出土的发现中有一块破碎的石板，上面刻着泰坦的文字，名为{link:goaz-stone}戈阿兹石{/link}。在东南方更高的山丘上，越过旧挖掘点，协会开辟了第二座营地，从那里有一条路通往{link:excavation-site}挖掘场{/link}。]=],
		},
	},
})

Translate("zhCN", "dun-algaz", {
	title = "丹奥加兹",
	sections = {
		{
			title = "概述",
			text = [=[丹奥加兹是{link:loch-modan}洛克莫丹{/link}与{link:wetlands}湿地{/link}之间的山口，其南端由{link:algaz-station}奥加兹岗哨{/link}的{link:dwarves}矮人{/link}把守。这是{link:ironforge}铁炉堡{/link}士兵经陆路抵达{link:menethil-harbor}米奈希尔港{/link}的唯一道路。{link:dragonmaw-clan}龙喉兽人{/link}向来只待在丘陵中，如今却在一名叫{link:ma-ruk-wyrmscale}马鲁克·龙鳞{/link}的督军率领下大举进入山口。米奈希尔无人说得清是什么驱使他们这样做。如果他们守住丹奥加兹，港口就将孤立无援。]=],
		},
	},
})

Translate("zhCN", "grim-batol", {
	title = "格瑞姆巴托",
	sections = {
		{
			title = "概述",
			text = [=[格瑞姆巴托是{link:wetlands}湿地{/link}极东处的一座山中要塞，位于{link:dragonmaw-clan}龙喉{/link}大门之后。它由蛮锤{link:dwarves}矮人{/link}建造。三锤之战后，黑暗巫术玷污了它的厅堂，蛮锤矮人便离开了这里。在{link:second-war}第二次战争{/link}中，龙喉氏族将它作为据点。他们凭借{link:deathwing}死亡之翼{/link}打造的一件神器之力，将红龙女王{link:alexstrasza}阿莱克丝塔萨{/link}锁在这里，并把她的后代养作战争坐骑。女王后来获得了自由。如今红龙聚集在格瑞姆巴托的大门前，不容陌生人靠近。]=],
		},
	},
})

Translate("zhCN", "angerfang-encampment", {
	title = "怒牙营地",
	sections = {
		{
			title = "概述",
			text = [=[怒牙营地是{link:dragonmaw-clan}龙喉兽人{/link}的战营，位于{link:wetlands}湿地{/link}大路以东的丘陵中。{link:second-war}第二次战争{/link}之后，少数从红龙的复仇中幸存的龙喉兽人逃离{link:grim-batol}格瑞姆巴托{/link}，藏身于这片山中。在{link:chieftain-nek-rosh}纳克罗什酋长{/link}的统领下，他们在这里重新强大起来。他们的战旗在营地上空飘扬，百夫长和暗影守卫者在营中操练，攻城投石车已准备好向{link:menethil-harbor}米奈希尔港{/link}进军。]=],
		},
	},
})

Translate("zhCN", "dragonmaw-retreat", {
	title = "龙喉隐匿处",
	sections = {
		{
			title = "概述",
			text = [=[龙喉隐匿处是{link:dragonmaw-clan}龙喉兽人{/link}在{link:wetlands}湿地{/link}东部丘陵中的一处隐秘据点。氏族在这里囤积武器，留给尚未武装起来的士兵。这里的战士不只是斗士：缚魂者和收复者行走其间，还有人看见一头龙人在那里，俯首屈服。{link:captain-stoutfist}斯托菲队长{/link}乐于看到这批储备在派上用场之前被夺走。{link:orcs}兽人{/link}想要收复的是什么，{link:dwarves}矮人{/link}们只能猜测。]=],
		},
	},
})

Translate("zhCN", "mosshide-fen", {
	title = "藓皮沼泽",
	sections = {
		{
			title = "概述",
			text = [=[藓皮沼泽是{link:wetlands}湿地{/link}南部的一片{link:the-marshlands}沼泽地{/link}带，靠近奥加兹的{link:dwarves}矮人{/link}关口。它得名于藓皮{link:gnolls}豺狼人{/link}。豺狼人在{link:swamp-of-sorrows}沼泽{/link}中安静地生活了许多年，但他们的数量增长了。他们践踏沼泽里的灌木与花草，砍伐树木作柴火，并随身带着粗糙的火石来生火。被称为{link:rethiel-the-greenwarden}绿色守护者{/link}的灵体已将他们视作这片土地上的一道伤口。]=],
		},
	},
})

Translate("zhCN", "sundown-marsh", {
	title = "日落沼泽",
	sections = {
		{
			title = "概述",
			text = [=[日落沼泽位于{link:wetlands}湿地{/link}北部，是一片布满水塘与芦苇的低洼湿地。藓皮{link:gnolls}豺狼人{/link}也在这里狩猎，其中有他们的秘法师和首领。更奇怪的东西从水中升起。{link:swamp-of-sorrows}沼泽{/link}爬行者在水道中蹒跚而行，更强大的沼泽领主立于其间。{link:rethiel-the-greenwarden}绿色守护者{/link}称它们是这片土地上发热的水疱，生于一种无人能解释的溃烂，它希望让它们重归沼泽。]=],
		},
	},
})

Translate("zhCN", "saltspray-glen", {
	title = "盐沫沼泽",
	sections = {
		{
			title = "概述",
			text = [=[盐沫沼泽是{link:wetlands}湿地{/link}西北部的一处谷地，迎着海上吹来的风。这里是迅猛龙的地盘。在此狩猎的锐齿迅猛龙因其牙齿而得名，那牙齿又长又尖，足以刺穿幼龙的鳞片；据说它们的蛋里，蛋黄有{link:gnomes}侏儒{/link}的脑袋那么大。{link:dwarves}矮人{/link}{link:howin-kindfeather}霍文·鹰羽{/link}派猎手来这里寻找这两样东西。]=],
		},
	},
})

Translate("zhCN", "ironbeard-s-tomb", {
	title = "铁须之墓",
	sections = {
		{
			title = "概述",
			text = [=[铁须之墓是{link:wetlands}湿地{/link}北部一处古老的{link:dwarves}矮人{/link}墓地，离{link:dun-modr}丹莫德{/link}不远。无论铁须是谁，这座墓都比他的名字存留得更久。如今滴淌的深红软泥在墓中爬行，吞噬它们碰到的一切。米奈希尔一位名叫希达的女子仍然每周来这里一次，不管有没有软泥；有一回，她不得不丢下包逃离它们。]=],
		},
		{ title = "未载", text = "没有任何编年史告诉我们铁须是谁、他何时安葬于此，或者希达为何前来拜访他的墓。" },
	},
})

Translate("zhCN", "direforge-hill", {
	title = "恶铁岭",
	sections = {
		{
			title = "概述",
			text = [=[恶铁岭耸立在{link:dun-modr}丹莫德{/link}以东。这里是{link:dark-iron-dwarves}黑铁矮人{/link}在{link:wetlands}湿地{/link}的主营地。他们的掘地者从这里挖掘，他们的破坏者从这里出发，他们的爆破手从这里运出炸毁{link:thandol-span}萨多尔大桥{/link}的火药。他们在这片土地上的主人是术士{link:balgaras-the-foul}邪恶的巴尔加拉斯{/link}，此人很少在战斗中露面。{link:longbraid-the-grim}长辫{/link}营地的{link:dwarves}矮人{/link}们知道，北方的战争将在这座山岭上见分晓。]=],
		},
	},
})

Translate("zhCN", "raptor-ridge", {
	title = "恐龙岭",
	sections = {
		{
			title = "概述",
			text = [=[恐龙岭是{link:wetlands}湿地{/link}东北部一片高耸的岩石台地。这里是锐齿迅猛龙的家园，一头强大的同类女族长统治着山岭。很少有猎人愿意攀上去。那些上去的人是为了锐齿迅猛龙的牙齿和蛋，而他们带着伤疤回来。]=],
		},
	},
})

Translate("zhCN", "bluegill-marsh", {
	title = "蓝腮沼泽",
	sections = {
		{
			title = "概述",
			text = [=[蓝腮沼泽位于{link:menethil-harbor}米奈希尔港{/link}以北的海岸。蓝腮{link:murlocs}鱼人{/link}从深水中爬上来，在岸边建起了它们的棚屋。它们袭击渔民和路上的商人；商船{i}盲眼公主号{/i}经过时，它们把船上的大部分货物拖下了海。一个名叫高布勒尔的鱼人从河湾率众劫掠，每次都会溜回棚屋的安全之处。]=],
		},
	},
})

Translate("zhCN", "black-channel-marsh", {
	title = "黑水沼泽",
	sections = {
		{
			title = "概述",
			text = [=[黑水沼泽是{link:wetlands}湿地{/link}西部一片由暗水与芦苇构成的迷宫，位于{link:menethil-harbor}米奈希尔港{/link}与{link:explorers-league}探险者协会{/link}的挖掘场之间。它的水道是巨鳄出没之地，米奈希尔的制革匠十分看重这些巨鳄；丘陵上的斑纹迅猛龙也会下到{link:swamp-of-sorrows}沼泽{/link}边缘捕猎。制革匠的学徒来这里剥鳄鱼皮，结果鳄鱼夺走了他的一条腿。]=],
		},
	},
})

Translate("zhCN", "the-green-belt", {
	title = "绿带草地",
