	sections = {
		{
			title = "概述",
			text = [=[绿带草地是{link:wetlands}湿地{/link}东部一条长长的草水之谷，位于大路分岔通往{link:dun-modr}丹莫德{/link}之处的东边。深红雏龙沿着它筑巢。因某种疾病而发狂的熊在山坡上游荡。{link:swamp-of-sorrows}沼泽{/link}之灵{link:rethiel-the-greenwarden}绿色守护者{/link}在这里的鳄鱼群中行走，而丘陵中的{link:orcs}兽人{/link}从不远离。]=],
		},
	},
})

Translate("zhCN", "the-lost-fleet", {
	title = "失落的舰队",
	sections = {
		{
			title = "概述",
			text = [=[失落的舰队是{link:wetlands}湿地{/link}西北海岸的一片沉船墓地。在{link:second-war}第二次战争{/link}中，{link:kul-tiras}库尔提拉斯{/link}的{link:third-fleet}第三舰队{/link}在红龙的烈焰下于此燃烧沉没。它的船体至今仍躺在浅滩中。船员们并未全都得到安息。其中一艘船上藏着某种受诅咒之物，它的力量将溺亡的水手和陆战队员困在腐朽的甲板上，他们的船长也在其中。]=],
		},
	},
})

Translate("zhCN", "thelgen-rock", {
	title = "瑟根石",
	sections = {
		{
			title = "概述",
			text = [=[瑟根石是{link:wetlands}湿地{/link}南部丘陵中的一个洞穴，位于{link:whelgar-s-excavation-site}维尔加挖掘点{/link}的东南。洞中满是蜘蛛，它们的毒液极强，米奈希尔的炼{link:ginro-hearthkindle}金{/link}师需要它们完好无损的毒腺来调制抗毒剂。一只名叫吸血寡妇的巨蛛在洞口附近捕猎。经过瑟根石的小路攀入{link:razorfen-downs}高地{/link}，{link:excavation-site}挖掘场{/link}就在那里。]=],
