			text = [=[勘察员维尔加领导着以他名字命名的{link:explorers-league}探险者协会{/link}挖掘场。他年纪大了，用他自己的话说，太老了，下不去那些占据他营地的野兽中间。但他头脑敏锐。就在迅猛龙到来之前，他挖出了一块巨大的石板，即{link:goaz-stone}戈阿兹石{/link}，上面刻着泰坦的文字，裂成了四处。他相信缺失的碎片握有解开一个谜团的钥匙，这个谜团比协会发现过的任何谜团都更宏大。]=],
		},
		{
			title = "意义",
			text = [=[维尔加的石板讲述了一个神圣的计划和一个注定的预言，还讲到了被锁在大地之下的上古之神。协会的发现中，很少有触及如此古老或如此黑暗之事的。]=],
		},
		{
			title = "事迹",
			text = [=[• 他持有{link:archaeologist-flagongut}考古学家弗拉冈特{/link}想要研究的那块最初的化石。
• 他与{link:merrin-rockweaver}麦琳·石纹{/link}和{link:ormer-ironbraid}奥莫尔·铁衣{/link}一同在迅猛龙对挖掘场的袭击中幸存。
• 他致力于翻译{link:goaz-stone}戈阿兹石{/link}上的泰坦文字。]=],
		},
		{ title = "未载", text = "没有任何编年史记载维尔加在挖掘之前的生平，也没有记载他为协会效力了多久。" },
	},
	chapters = {
		{
			title = "戈阿兹石",
			hint = "找回勘探员石板上缺失的碎片。",
			text = [=[这些碎片名为阿多斯、莫德、戈尔姆和奈鲁，散落在挖掘场的废墟中，夹在古老的遗物和松散的泥土之间。当最后一块被嵌回原位，维尔加俯身于石板之上，开始阅读。新的字句立刻浮现在他眼前，他大声念了出来：上古之神，被锁在大地之下。他没有说他担心这意味着什么。他只说，这是某件伟大之事的开端。]=],
		},
	},
	mentions = {
		{ text = "揭开过去" },
		{ text = "健忘的勘探员" },
		{ text = "寻找挖掘队" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "麦琳·石纹", note = "他队里的一名挖掘者" },
		{ id = "ormer-ironbraid", name = "奥莫尔·铁衣", note = "救了他的命" },
		{ id = "archaeologist-flagongut", name = "考古学家弗拉冈特", note = "想要他的化石" },
	},
})

