	hint = "找到那位带着狮鹫、在维尔加挖掘场以东路旁扎营的矮人。",
	allegiance = "蛮锤部族",
	aliases = { "霍文" },
	sections = {
		{
			title = "概述",
			text = [=[霍文·鹰羽带着他的狮鹫低音喙在{link:wetlands}湿地{/link}大路旁扎营。他曾让这只鸟带着一封信飞进米奈希尔订购雏龙鳞片，港口的制革匠至今仍为此惊叹。他一提起{link:dark-iron-dwarves}黑铁矮人{/link}、{link:dragonmaw-clan}龙喉氏族{/link}以及他们骑过的幼龙就啐上一口，拿不定主意最恨哪一个。他打算拨乱反正。他的计划需要一件抵御龙焰的斗篷，缝制它的牙齿，以及一只吃饱了的狮鹫。]=],
		},
		{ title = "事迹", text = [=[• 他收购深红雏龙的鳞片，这些鳞片能抵御龙焰。
• 他为他的计划收集锐齿迅猛龙的牙齿和蛋。]=] },
	},
	mentions = {
		{ text = "深红货箱的递送" },
		{ text = "锐齿之针" },
		{ text = "艰难时刻" },
	},
	bonds = {
		{ id = "james-halloran", name = "詹姆斯·哈洛兰", note = "把鳞片卖给了他" },
	},
})

