Translate("zhCN", "chieftain-nek-rosh", {
	title = "纳克罗什酋长",
	subtitle = "龙喉氏族酋长",
	found = "怒牙营地",
	hint = "面对那位在东部丘陵的营地中统领龙喉氏族的酋长。",
	allegiance = "龙喉氏族",
	aliases = { "奈克罗什" },
	sections = {
		{
			title = "概述",
			text = [=[奈克罗什是{link:wetlands}湿地{/link}{link:dragonmaw-clan}龙喉氏族{/link}的酋长。他是耐克鲁斯之子，耐克鲁斯曾在氏族囚禁红龙的那些年里统领氏族。耐克鲁斯用强大的魔法让巨龙屈服于他的意志。魔法失效后，巨龙转而攻击它们的主人，耐克鲁斯被杀。他的儿子发誓要向杀死父亲的巨龙复仇。]=],
		},
		{
			title = "意义",
			text = [=[在奈克罗什的统领下，一个破碎的氏族重新变成了一支军队。{link:dragonmaw-clan}龙喉氏族{/link}已推进到{link:dun-algaz}丹奥加兹{/link}，建造攻城器械，并将目光投向了{link:menethil-harbor}米奈希尔港{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:angerfang-encampment}怒牙营地{/link}召集了四散的{link:dragonmaw-clan}龙喉兽人{/link}。
• 他驱使战士进入{link:dun-algaz}丹奥加兹{/link}，切断了米奈希尔与{link:loch-modan}洛克莫丹{/link}之间的道路。
• 他建造投石车，准备围攻{link:menethil-harbor}米奈希尔港{/link}。]=],
		},
		{
			title = "未载",
			text = [=[{link:second-war}第二次战争{/link}的编年史讲述了{link:dragonmaw-clan}龙喉氏族{/link}在{link:grim-batol}格瑞姆巴托{/link}囚禁巨龙女王的事。至于奈克罗什本人在那些年里扮演了什么角色，它们没有提及。]=],
		},
	},
	chapters = {
		{
			title = "耐克鲁斯之子",
			hint = "把龙喉氏族的战旗交给米奈希尔城堡里的上尉。",
			text = [=[战旗被摆在面前时，{link:captain-stoutfist}斯托菲队长{/link}讲出了{link:dwarves}矮人{/link}们对这个敌人所知的一切。{link:dragonmaw-clan}龙喉氏族{/link}已不再是他们骑龙时的样子。他们的酋长是那个曾经奴役红龙军团的{link:orcs}兽人{/link}之子，他没有忘记父亲是怎么死的。]=],
		},
		{
			title = "击败奈克罗什",
			hint = "烧毁投石车，击倒酋长。",
			text = [=[投石车先被烧毁，米奈希尔免于它们的威胁。接着奈克罗什倒在了自己的营地中。{link:captain-stoutfist}壮拳{/link}认为这是沉重的一击，氏族也许再也无法恢复。]=],
		},
	},
	mentions = {
		{ text = "战旗" },
		{ text = "奈克罗什的赌注" },
		{ text = "击败奈克罗什" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "斯托菲队长", note = "敌人" },
		{ id = "ma-ruk-wyrmscale", name = "马鲁克·龙鳞", note = "他在丹奥加兹的督军" },
		{ id = "alexstrasza", name = "阿莱克丝塔萨", note = "被他父亲奴役的巨龙的女王" },
	},
})

Translate("zhCN", "ma-ruk-wyrmscale", {
	title = "马鲁克·龙鳞",
	subtitle = "龙喉督军",
	found = "丹奥加兹",
