Translate("zhCN", "dragonmaw-clan", {
	title = "龙喉氏族",
	aliases = { "龙喉", "龙喉兽人", "龙喉氏族兽人" },
	sections = {
		{
			title = "概述",
			text = [=[龙喉是旧{link:horde}部落{/link}的一个{link:orcs}兽人{/link}氏族。在{link:second-war}第二次战争{/link}中，他们做到了其他氏族都做不到的事：让红龙成为他们的仆从。他们从{link:grim-batol}格瑞姆巴托{/link}的据点出发，凭借{link:deathwing}死亡之翼{/link}所铸神器的力量囚禁了巨龙女王{link:alexstrasza}阿莱克丝塔萨{/link}，并把她的后代养作战争坐骑。龙喉兽人驾驭的红龙在海上焚烧了{link:alliance}联盟{/link}的船只。]=],
		},
		{
			title = "覆灭",
			text = [=[束缚巨龙的魔法失效了。红龙军团转而攻击这个氏族，毫不留情地追杀他们。曾统领龙喉氏族的耐克鲁斯被杀，氏族几近覆灭。少数幸存者逃离{link:grim-batol}格瑞姆巴托{/link}，藏身于{link:wetlands}湿地{/link}大路以东的群山中。]=],
		},
		{
			title = "如今",
			text = [=[在耐克鲁斯之子{link:chieftain-nek-rosh}纳克罗什酋长{/link}的统领下，龙喉氏族重新强大起来。他们从{link:angerfang-encampment}怒牙营地{/link}和隐秘的{link:dragonmaw-retreat}龙喉隐匿处{/link}向西出击，并夺取了{link:dun-algaz}丹奥加兹{/link}山口。他们建造投石车，囤积武器，据传仍然梦想着巨龙。米奈希尔的{link:dwarves}矮人{/link}称他们凶猛，但也知道，失去巨龙的龙喉氏族远不及当年那个遮天蔽日的氏族那般可怕。]=],
		},
	},
})

Translate("zhCN", "third-fleet", {
	title = "第三舰队",
	aliases = { "厄运舰队" },
	sections = {
		{
			title = "概述",
			text = [=[{link:kul-tiras}库尔提拉斯{/link}的第三舰队在{link:second-war}第二次战争{/link}中出航，那是对{link:horde}部落{/link}的最后一场大战。它的船只来自{link:lordaeron}洛丹伦{/link}的海岸，至少有一艘并非属于它的船为求保护而加入：{i}飞翔鱼鹰号{/i}，它载着一批光铸铁。在{link:wetlands}湿地{/link}海岸外，骑着红龙的{link:orcs}兽人{/link}扑向了舰队。船只燃烧沉没，残骸至今仍躺在西北海岸，那地方被称为{link:the-lost-fleet}失落的舰队{/link}。]=],
		},
		{
			title = "诅咒",
			text = [=[{i}无畏号{/i}上藏着某样东西：一只被诅咒的帕{link:farmer-ray}雷{/link}斯之眼，锁在船长的保险箱里。这些眼睛由{link:humans}人类{/link}牧师制造，本应闪耀着神圣之光，但这一只目睹了太多悲伤。它的力量将溺亡的船员困在腐朽的船体中。舰队中只有一人仍然活着，他就是{link:first-mate-fitzsimmons}大副菲兹莫斯{/link}；他在米奈希尔酗酒，好让自己不再梦见他们。]=],
		},
		{
			title = "货物",
			text = [=[海岸的{link:murlocs}鱼人{/link}已把{i}飞翔鱼鹰号{/i}搜刮了一遍。它的光铸铁锭深受对抗亡灵者的珍视。{link:teldrassil}泰达希尔{/link}的{link:night-elves}暗夜精灵{/link}{link:sylessa-duskwhisper}希莱萨·暮语{/link}说，这艘船还载着诺德尔，一朵来自{link:mount-hyjal}海加尔山{/link}的花。]=],
		},
	},
})

Translate("zhCN", "goaz-stone", {
	title = "戈阿兹石",
	aliases = { "戈阿兹石板" },
	sections = {
		{
			title = "概述",
			text = [=[戈阿兹石是{link:prospector-whelgar}勘察员维尔加{/link}在{link:wetlands}湿地{/link}的挖掘场出土的一块巨大石板，就在迅猛龙冲垮营地之前。它上面刻着泰坦的文字。发现时，它已裂成四处，丢失的碎片分别名为阿多斯、莫德、戈尔姆和奈鲁。即便残缺不全，这块石板也讲述了一个神圣的计划和一个注定的预言。]=],
		},
		{
			title = "解读",
			text = [=[四块碎片复原后，{link:prospector-whelgar}维尔加{/link}开始了缓慢的翻译工作。他读到的第一批新字句讲述了上古之神，被锁在大地之下。{link:explorers-league}探险者协会{/link}以前也发现过泰坦的刻文，但很少有如此直白地讲述地下之物的。]=],
		},
		{
			title = "当今",
			text = [=[{link:prospector-whelgar}维尔加{/link}尚未读完。在他挖掘场上方的丘陵中，雾气开始从山上降下，泰坦的构造体再度行走。这块石头与{link:razorfen-downs}高地{/link}的异动是否有关，协会尚不知晓。]=],
		},
	},
})
